// Twilio POSTs application/x-www-form-urlencoded — n8n's webhook node parses it into .body already.
const crypto = require('crypto');
const b = items[0].json.body || {};
const headers = items[0].json.headers || {};
const sig = headers['x-twilio-signature'] || headers['X-Twilio-Signature'] || '';
const authToken = '{{CREA_TWILIO_AUTH_TOKEN}}';
const publicUrl = ('{{CREA_PUBLIC_BASE_URL}}').replace(/\/$/, '') + '/webhook/crea-voice-inbound';
const REJECT = '<?xml version="1.0" encoding="UTF-8"?><Response><Reject/></Response>';

function validTwilioSig(url, params, token, signature) {
  if (!token || !signature) return false;
  const sorted = Object.keys(params).sort();
  let data = url;
  for (const k of sorted) data += k + params[k];
  const expected = crypto.createHmac('sha1', token).update(Buffer.from(data, 'utf-8')).digest('base64');
  return expected === signature;
}

if (!validTwilioSig(publicUrl, b, authToken, sig)) {
  return [{ json: { valid: false, twiml: REJECT } }];
}
const from = String(b.From || '').replace(/[^0-9]/g, '');
if (!from) return [{ json: { valid: false, twiml: REJECT } }];
const speechResult = String(b.SpeechResult || '').trim().slice(0, 1000);
const callSid = String(b.CallSid || '');
return [{ json: { valid: true, from, speechResult, callSid, isFirstTurn: !speechResult } }];

const inc = $node['Verify & Parse'].json;
const stored = items[0].json || {};
const now = Date.now();

// blocklist — checked every turn, same list WhatsApp uses
const blocked = ('{{CREA_BLOCKLIST}}'.match(/\d{5,}/g) || []);
if (blocked.includes(inc.from)) return [{ json: { ...inc, outcome: 'reject' } }];

// the rest only need checking once per call, at the first turn — a normal booking call is
// many Gather turns and treating each turn as a fresh "attempt" would misfire on flood.
if (!inc.isFirstTurn) return [{ json: { ...inc, outcome: 'continue' } }];

// 3-day quiet period after a handoff to the owner — same rule as crea-01
const daysSinceHuman = stored.humanSince ? (now - Date.parse(stored.humanSince)) / 864e5 : 999;
if (stored.mode === 'human' && daysSinceHuman < 3) return [{ json: { ...inc, outcome: 'human' } }];

// call-attempt flood — a 5min window (phone abuse is slower-moving than a text flood, and
// each call is many turns already so we're counting NEW calls, not turns)
const RATE = Math.max(2, parseInt('{{CREA_RATE_LIMIT_PER_MIN}}', 10) || 12);
const threshold = Math.max(3, Math.floor(RATE / 2));
const callTimes = (Array.isArray(stored.callTimes) ? stored.callTimes : []).filter(x => now - x < 300000).concat(now).slice(-40);
if (callTimes.length > threshold) return [{ json: { ...inc, outcome: 'flood', callTimes } }];

return [{ json: { ...inc, outcome: 'continue', callTimes } }];

const voice = '{{CREA_VOICE_NAME}}' || 'Polly.Olivia-Neural';
const lang = '{{CREA_VOICE_LANG}}' || 'en-AU';
const twiml = '<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="' + voice + '" language="' + lang + '">We are getting a lot of calls from this number right now — please try again in a few minutes.</Say><Hangup/></Response>';
return [{ json: { twiml } }];

const OWNER = '{{CREA_OWNER_NAME}}';
const voice = '{{CREA_VOICE_NAME}}' || 'Polly.Olivia-Neural';
const lang = '{{CREA_VOICE_LANG}}' || 'en-AU';
const twiml = '<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="' + voice + '" language="' + lang + '">Thanks for calling — ' + OWNER + ' already has your details and will be in touch shortly.</Say><Hangup/></Response>';
return [{ json: { twiml } }];

const B = '{{CREA_BUSINESS_NAME}}';
const voice = '{{CREA_VOICE_NAME}}' || 'Polly.Olivia-Neural';
const lang = '{{CREA_VOICE_LANG}}' || 'en-AU';
const actionUrl = ('{{CREA_PUBLIC_BASE_URL}}').replace(/\/$/, '') + '/webhook/crea-voice-inbound';
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const greeting = 'Thanks for calling ' + B + '. Are you after photos, video, or both, or something else?';
const twiml = '<?xml version="1.0" encoding="UTF-8"?><Response><Gather input="speech" action="' + esc(actionUrl) + '" method="POST" speechTimeout="auto" language="' + lang + '"><Say voice="' + voice + '" language="' + lang + '">' + esc(greeting) + '</Say></Gather><Say voice="' + voice + '" language="' + lang + '">Sorry, I did not catch that.</Say><Redirect method="POST">' + esc(actionUrl) + '</Redirect></Response>';
return [{ json: { twiml } }];

const s = items[0].json || {};
const voice = '{{CREA_VOICE_NAME}}' || 'Polly.Olivia-Neural';
const lang = '{{CREA_VOICE_LANG}}' || 'en-AU';
const actionUrl = ('{{CREA_PUBLIC_BASE_URL}}').replace(/\/$/, '') + '/webhook/crea-voice-inbound';
const esc = x => String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const reply = s._lastReply || "Sorry, could you say that again?";
const wrapUp = !!s._lastConfirmed || !!s._lastNeedsHuman;
let twiml;
if (wrapUp) {
  twiml = '<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="' + voice + '" language="' + lang + '">' + esc(reply) + '</Say><Pause length="1"/><Say voice="' + voice + '" language="' + lang + '">Thanks for calling, goodbye.</Say><Hangup/></Response>';
} else {
  twiml = '<?xml version="1.0" encoding="UTF-8"?><Response><Gather input="speech" action="' + esc(actionUrl) + '" method="POST" speechTimeout="auto" language="' + lang + '"><Say voice="' + voice + '" language="' + lang + '">' + esc(reply) + '</Say></Gather><Say voice="' + voice + '" language="' + lang + '">Sorry, I did not catch that.</Say><Redirect method="POST">' + esc(actionUrl) + '</Redirect></Response>';
}
return [{ json: { twiml } }];
